<?php
header('Content-Type: application/json; charset=utf-8');
if ($_SERVER['REQUEST_METHOD'] !== 'POST') { http_response_code(405); exit; }
$action=(string)($_POST['action']??''); $tema=(int)($_POST['tema_id']??0); $target=(int)($_POST['target']??0);
$db=new mysqli('localhost','root','','discoteca'); if($db->connect_errno){http_response_code(500);echo json_encode(array('ok'=>false));exit;}$db->set_charset('utf8');
$valid=$db->prepare("SELECT c.tema_id FROM sampler_fx_config c INNER JOIN temas t ON t.id=c.tema_id WHERE c.tema_id=? AND t.categoria='rafagasfx'");$valid->bind_param('i',$tema);$valid->execute();if(!$valid->get_result()->num_rows){http_response_code(400);echo json_encode(array('ok'=>false));exit;}
if($action==='assign_key'){$key=strtoupper(trim((string)($_POST['atajo']??'')));if($key!==''&&!preg_match('/^[A-Z0-9]{1,16}$/',$key)){http_response_code(400);echo json_encode(array('ok'=>false));exit;}$db->begin_transaction();if($key!==''){$q=$db->prepare('UPDATE sampler_fx_config SET atajo=NULL WHERE atajo=?');$q->bind_param('s',$key);$q->execute();}$q=$db->prepare('UPDATE sampler_fx_config SET atajo=?,actualizado_en=NOW() WHERE tema_id=?');$q->bind_param('si',$key,$tema);$q->execute();$db->commit();echo json_encode(array('ok'=>true));exit;}
if($action==='set_fixed'){$fijado=(int)($_POST['fijado']??0)?1:0;$q=$db->prepare('UPDATE sampler_fx_config SET fijado=?,actualizado_en=NOW() WHERE tema_id=?');$q->bind_param('ii',$fijado,$tema);$q->execute();echo json_encode(array('ok'=>true));exit;}
if(!in_array($action,array('top','bottom','position','swap'),true)){http_response_code(400);echo json_encode(array('ok'=>false));exit;}
$bloqueo=$db->prepare('SELECT fijado FROM sampler_fx_config WHERE tema_id=?');$bloqueo->bind_param('i',$tema);$bloqueo->execute();if((int)$bloqueo->get_result()->fetch_assoc()['fijado']===1){http_response_code(409);echo json_encode(array('ok'=>false,'locked'=>true));exit;}
$db->begin_transaction();$rows=$db->query("SELECT c.tema_id FROM sampler_fx_config c INNER JOIN temas t ON t.id=c.tema_id WHERE t.categoria='rafagasfx' ORDER BY c.posicion FOR UPDATE")->fetch_all(MYSQLI_ASSOC);$ids=array_map('intval',array_column($rows,'tema_id'));$from=array_search($tema,$ids,true);if($from===false){$db->rollback();http_response_code(400);echo json_encode(array('ok'=>false));exit;}if($action==='top')$to=0;elseif($action==='bottom')$to=count($ids)-1;elseif($action==='swap'){$to=array_search($target,$ids,true);if($to===false){$db->rollback();http_response_code(400);echo json_encode(array('ok'=>false));exit;}$tmp=$ids[$from];$ids[$from]=$ids[$to];$ids[$to]=$tmp;$to=null;}else $to=max(0,min(count($ids)-1,$target-1));if($to!==null){$moving=$ids[$from];array_splice($ids,$from,1);array_splice($ids,$to,0,array($moving));}$db->query('UPDATE sampler_fx_config SET posicion=posicion+100000');$up=$db->prepare('UPDATE sampler_fx_config SET posicion=?,actualizado_en=NOW() WHERE tema_id=?');foreach($ids as $i=>$id){$pos=$i+1;$up->bind_param('ii',$pos,$id);$up->execute();}$db->commit();echo json_encode(array('ok'=>true));
